import{_ as d,C as n,o as l,c as i,j as t,a,E as r,a2 as s}from"./chunks/framework.BSl-aDiU.js";const y=JSON.parse('{"title":"5. Roadmap & open questions","description":"","frontmatter":{},"headers":[],"relativePath":"gdd/roadmap.md","filePath":"gdd/roadmap.md"}'),h={name:"gdd/roadmap.md"},p={id:"_5-1-what-exists-today",tabindex:"-1"},u={id:"_5-2-roadmap",tabindex:"-1"};function f(c,e,m,g,b,v){const o=n("Badge");return l(),i("div",null,[e[6]||(e[6]=t("h1",{id:"_5-roadmap-open-questions",tabindex:"-1"},[a("5. Roadmap & open questions "),t("a",{class:"header-anchor",href:"#_5-roadmap-open-questions","aria-label":'Permalink to "5. Roadmap & open questions"'},"​")],-1)),t("h2",p,[e[0]||(e[0]=a("5.1 What exists today ",-1)),r(o,{type:"tip",text:"Live"}),e[1]||(e[1]=a()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#_5-1-what-exists-today","aria-label":'Permalink to "5.1 What exists today <Badge type="tip" text="Live" />"'},"​",-1))]),e[7]||(e[7]=s("<ul><li>Full, compact hangar grid (fighters and walls only) per level; fighters launch only through a clear path to the top</li><li>Flight zone capped at 5 fighters (its HP and enemy fire are built but switched off for now)</li><li>Fighters line up under their target and fire straight up (no homing), colour-matched, no wasted bullets; empty fighters fly off screen</li><li>Front-first shielding for enemies and boss parts</li><li>Regular enemies in 3 sizes (3 / 6 / 9 hp) that fire every 3 s, and a multi-part boss whose parts each have their own weapon and stop firing when destroyed</li><li>Enemy bullets vanish when their shooter is destroyed</li><li>Multi-stage levels with a stage progress row in the HUD, win and lose screens, a home screen whose Play button continues from the first uncleared level</li><li>35 levels in seven difficulty ramps: core rules (1–5), elevators (6–10), mystery (11–15), mystery + elevators (16–20), frozen (21–25), two obstacles (26–35, with all three on 30 and 35)</li><li>Three obstacles: elevator (fixed fighter queue), mystery fighter (hidden colour), frozen fighter (thaws after N launches), each introduced by tutorial cards</li><li>Idle animation for fighters that can launch</li><li>Three boss spaceship designs (raptor, mantis, dreadnought)</li><li>Level checker: balance, structure and a solver that proves each level is winnable</li></ul>",1)),t("h2",u,[e[3]||(e[3]=a("5.2 Roadmap ",-1)),r(o,{type:"warning",text:"Coming soon"}),e[4]||(e[4]=a()),e[5]||(e[5]=t("a",{class:"header-anchor",href:"#_5-2-roadmap","aria-label":'Permalink to "5.2 Roadmap <Badge type="warning" text="Coming soon" />"'},"​",-1))]),e[8]||(e[8]=s('<p>Order of priority. Milestones are scope buckets, not dates.</p><h3 id="m2-feel-and-feedback" tabindex="-1">M2: Feel and feedback <a class="header-anchor" href="#m2-feel-and-feedback" aria-label="Permalink to &quot;M2: Feel and feedback&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Item</th><th>Chapter</th></tr></thead><tbody><tr><td>Sound effects and music</td><td><a href="./core-loop">Core loop</a></td></tr><tr><td>Highlight the tap path before launch; preview which enemies a fighter will hit</td><td><a href="./rules">Rules</a></td></tr><tr><td>Short tutorial overlay on level 1</td><td><a href="./core-loop">Core loop</a></td></tr></tbody></table><h3 id="m3-depth" tabindex="-1">M3: Depth <a class="header-anchor" href="#m3-depth" aria-label="Permalink to &quot;M3: Depth&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Item</th><th>Chapter</th></tr></thead><tbody><tr><td>Star rating per level (taps, time, or slots never full)</td><td><a href="./core-loop">Core loop</a></td></tr><tr><td>New blockers: locked fighters, crates that break after N launches</td><td><a href="./rules">Rules</a></td></tr><tr><td>Boss phases: new weapons or parts once half the parts are down</td><td><a href="./rules">Rules</a></td></tr><tr><td>20+ levels made with the checker</td><td><a href="./levels">Levels</a></td></tr></tbody></table><h2 id="known-issues" tabindex="-1">5.3 Known issues <a class="header-anchor" href="#known-issues" aria-label="Permalink to &quot;5.3 Known issues {#known-issues}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Issue</th><th>Impact</th><th>Planned fix</th></tr></thead><tbody><tr><td>Fighters in the flight zone can overlap while patrolling or lining up under the same target</td><td>Cosmetic</td><td>Spread lanes or add separation</td></tr><tr><td>The level checker doesn&#39;t model time, so it can&#39;t prove a level survivable on zone HP</td><td>A level could be winnable but too punishing</td><td>HP is tuned by playtesting (see <a href="./levels#hp-tuning">Levels 4.4</a>)</td></tr><tr><td>No level select</td><td>Players can&#39;t replay an earlier level from the home screen</td><td>Add a level map once there are more levels (<code>?level=N</code> works for testing)</td></tr><tr><td>No undo; one wrong tap can doom a hard level</td><td>The last level of each block is unforgiving</td><td>Consider an undo or &quot;recall&quot; power-up (M3)</td></tr></tbody></table><h2 id="open-questions" tabindex="-1">5.4 Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;5.4 Open questions {#open-questions}&quot;">​</a></h2><p>The prototype made these calls where the brief left room. Each is easy to change.</p><table tabindex="0"><thead><tr><th>Question</th><th>Options</th><th>Current lean</th></tr></thead><tbody><tr><td>Which board edge is the exit?</td><td>Top only · any edge</td><td><strong>Top only</strong>: the flight zone sits above the board, and it makes paths a real puzzle</td></tr><tr><td>Do walls block paths?</td><td>Yes · only fighters block</td><td><strong>Yes</strong></td></tr><tr><td>What does a fighter do with no matching enemy?</td><td>Patrol idle · return to the board</td><td><strong>Patrol idle</strong>, occupying its slot (the main source of tension)</td></tr><tr><td>How much HP does one enemy bullet take?</td><td>1 · 10 · scale with level</td><td><strong>10</strong>: with 1, enemies would have to live ~2 minutes each to matter; 10 leaves a fast player about half the HP on the hardest level</td></tr><tr><td>Which enemies fire?</td><td>All · only unshielded ones</td><td><strong>All</strong>, including shielded ones</td></tr><tr><td>Is shielding per column or per row?</td><td>Overlap-based (line of fire) · whole front row first</td><td><strong>Overlap-based</strong>: matches straight bullets</td></tr><tr><td>Turn enemy fire and zone HP back on?</td><td>On · off</td><td><strong>Off for now</strong>, to tune the puzzle on its own first. One flag (<code>RULES.enemyFire</code>)</td></tr><tr><td>Keep the instant &quot;Out of space&quot; loss now that the zone has HP?</td><td>Keep · let HP drain instead</td><td><strong>Keep</strong>: a jammed zone can never recover, so making the player wait is pointless</td></tr><tr><td>Can bullets be wasted on overkill?</td><td>Yes · no</td><td><strong>No</strong>: required so the balance rule guarantees a win</td></tr><tr><td>Where do empty fighters go?</td><td>Off the top · off the sides</td><td><strong>Off the top</strong></td></tr></tbody></table>',10))])}const k=d(h,[["render",f]]);export{y as __pageData,k as default};
